Voici une fonction C++ qui prend une référence à un std::string contenant du texte au format Markdown et renvoie un std::string contenant du texte au format HTML :

```cpp
#include <iostream>
#include <string>
#include <boost/algorithm/string.hpp> // pour boost::algorithm::replace_all()

std::string convertMarkdownToHtml(std::string& markdown) {
    // Remplacement des balises Markdown par leurs équivalents HTML
    boost::algorithm::replace_all(markdown, "\\n", "\n");
    boost::algorithm::replace_all(markdown, "\\t", "\t");
    boost::algorithm::replace_all(markdown, "\n\n", "<br><br>");
    boost::algorithm::replace_all(markdown, "\n", "<br>");
    boost::algorithm::replace_all(markdown, "**", "<strong>");
    boost::algorithm::replace_all(markdown, "__", "<strong>");
    boost::algorithm::replace_all(markdown, "*", "<em>");
    boost::algorithm::replace_all(markdown, "_", "<em>");
    boost::algorithm::replace_all(markdown, "``", "<pre>");
    boost::algorithm::replace_all(markdown, "```", "</pre>");
    boost::algorithm::replace_all(markdown, "```\n", "<pre>");
    boost::algorithm::replace_all(markdown, "```", "</pre>\n");
    boost::algorithm::replace_all(markdown, "[", "<a href=\"");
    boost::algorithm::replace_all(markdown, "]", "\"></a>");
    boost::algorithm::replace_all(markdown, "!(.*?)\(", "<img src=\"");
    boost::algorithm::replace_all(markdown, "(. *\ )", "\"></img>");
    boost::algorithm::replace_all(markdown, "~~", "<s>");
    boost::algorithm::replace_all(markdown, "~~", "</s>");

    return markdown;
}

int main() {
    std::string markdown = "Hello **world**! \n This is a *test*.\n\n A link: [Google](https://www.google.com/). \n An image: ! [Boost](https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/Boost-logo-variant-LGCC.svg/1200px-Boost-logo-variant-LGCC.svg.png). \n\n Here's a block of code:\n```\n#include <iostream>\n\nint main() {\n    std::cout << \"Hello, world!\" << std::endl;\n    return 0;\n}\n```\n\n Strikethrough: This is ~~strikethrough~~ text.";

    std::string html = convertMarkdownToHtml(markdown);
    std::cout << "Markdown:\n" << markdown << "\n\nHTML:\n" << html << std::endl;

    return 0;
}
```

