```javascript
function checkPrime(arr) {
  // Vérifier que le tableau contient exactement 5 nombres
  if (arr.length !== 5) {
    console.error("Le tableau doit contenir exactement 5 nombres");
    return;
  }

  // Boucler sur chaque nombre du tableau
  for (let I = 0; I < arr.length; i++) {
    const num = arr[i];

    // Vérifier que le nombre est un entier positif
    if (typeof num !== 'number' || num <= 0 || !Number.isInteger(num)) {
      console.error(`Le nombre ${num} n'est pas un entier positif`);
      continue;
    }

    // Vérifier si le nombre est premier
    let isPrime = true;
    for (let j = 2; j * j <= num; j++) {
      if (num % j === 0) {
        isPrime = false;
        break;
      }
    }

    // Imprimer le nombre premier (si il y en a un) sur la console
    if (isPrime) {
      console.log(`Le nombre premier dans le tableau est ${num}`);
      return;
    }
  }
}
```

